SqlNo=3
SQLNode {
    sqlTemplate='SELECT n.id, e.id, CAST(JSON_UNQUOTE(JSON_EXTRACT(n.props, '$.archetype.forum_id')) AS SIGNED) AS forum_id , JSON_UNQUOTE(JSON_EXTRACT(n.props, '$.archetype.title')) AS title FROM ( SELECT e.* FROM anchors e WHERE e.dst = ? AND e.kind = 'EdgeAnchor' AND (e.arch_type = ? OR e.arch_type IN ( SELECT type_name FROM graph_types WHERE ancestor = ? )) AND (e.src_type IS NULL OR e.src_type = ? OR e.src_type IN ( SELECT type_name FROM graph_types WHERE ancestor = ? )) UNION ALL SELECT e.* FROM anchors e WHERE e.src = ? AND e.undirected = 1 AND e.src <> e.dst AND e.kind = 'EdgeAnchor' AND (e.arch_type = ? OR e.arch_type IN ( SELECT type_name FROM graph_types WHERE ancestor = ? )) AND (e.dst_type IS NULL OR e.dst_type = ? OR e.dst_type IN ( SELECT type_name FROM graph_types WHERE ancestor = ? )) ) e JOIN anchors n ON n.id = CASE  WHEN e.src = ? THEN e.dst ELSE e.src END AND n.kind = 'NodeAnchor' AND (n.arch_type = ? OR n.arch_type IN ( SELECT type_name FROM graph_types WHERE ancestor = ? )) WHERE CAST(JSON_UNQUOTE(JSON_EXTRACT(e.props, '$.archetype.joinDate')) AS SIGNED) > ? ORDER BY e.seq, e.id',
    parameters={RS_q1_r1_col1:VARCHAR, "HasMember":VARCHAR, "HasMember":VARCHAR, "Forum":VARCHAR, "Forum":VARCHAR, RS_q1_r1_col1:VARCHAR, "HasMember":VARCHAR, "HasMember":VARCHAR, "Forum":VARCHAR, "Forum":VARCHAR, RS_q1_r1_col1:VARCHAR, "Forum":VARCHAR, "Forum":VARCHAR, M_J_field_REQUEST_PARAM_min_date_java_lang_Long_value:BIGINT},
    retVals={n.id:VARCHAR, e.id:VARCHAR, forum_id:BIGINT, title:LONGTEXT}
}
